import itertools
for n in [8,9,10,11]:
    r=[]
    for f in itertools.product(range(3),repeat=n):
        if len(set(f))<3: continue
        S={}
        ok=True
        for i in range(n):
            for j in range(n):
                if f[i]!=f[j]:
                    k=3-f[i]-f[j]
                    if S.setdefault(i+j+2,k)!=k: ok=False;break
            if not ok:break
        if ok:r.append(f)
    print(n,len(r))
    if n==10:
        for x in r:print(''.join(map(str,x)))
